// frontend/src/pages/DashboardPage.jsx
// Main page shown after login — skill input + roadmap display

import { useState, useEffect } from 'react';
import { generateRoadmap, getRoadmaps, markTopic } from '../api/api';
import RoadmapCard from '../components/RoadmapCard';
import SkillInput from '../components/SkillInput';

// Career goal options shown in the dropdown
const CAREER_GOALS = [
  'Full Stack Developer',
  'Backend Developer',
  'Data Analyst',
];

function DashboardPage({ onLogout }) {
  const username = localStorage.getItem('username');

  // Form state
  const [careerGoal, setCareerGoal] = useState(CAREER_GOALS[0]);
  const [skills, setSkills] = useState([]);         // List of skill strings

  // Data state
  const [roadmaps, setRoadmaps] = useState([]);     // Previously saved roadmaps
  const [newRoadmap, setNewRoadmap] = useState(null); // Freshly generated roadmap

  // UI state
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  // Load previous roadmaps when the page first opens
  useEffect(() => {
    loadRoadmaps();
  }, []);

  const loadRoadmaps = async () => {
    try {
      const res = await getRoadmaps(); // GET /api/roadmap/list/
      setRoadmaps(res.data);
    } catch {
      console.error('Could not load roadmaps');
    }
  };

  // Called when user clicks "Generate Roadmap"
  const handleGenerate = async () => {
    if (skills.length === 0) {
      setError('Please add at least one skill.');
      return;
    }
    setError('');
    setLoading(true);

    try {
      // POST skills and goal to Django — it returns a generated roadmap
      const res = await generateRoadmap(careerGoal, skills);
      setNewRoadmap(res.data);    // Show the new roadmap at the top
      loadRoadmaps();             // Refresh the saved roadmaps list
    } catch {
      setError('Failed to generate roadmap. Is the backend running?');
    } finally {
      setLoading(false);
    }
  };

  // Toggle a topic as complete/incomplete
  const handleMarkTopic = async (roadmapId, topicName, currentStatus) => {
    await markTopic(roadmapId, topicName, !currentStatus);
    loadRoadmaps(); // Refresh to show updated progress
  };

  return (
    <div className="dashboard">

      {/* Top navigation bar */}
      <nav className="navbar">
        <span className="nav-logo">🗺 Career Roadmap</span>
        <div className="nav-right">
          <span className="nav-user">Hi, {username}</span>
          <button className="logout-btn" onClick={onLogout}>Logout</button>
        </div>
      </nav>

      <div className="dashboard-body">

        {/* Left panel: input form */}
        <div className="input-panel">
          <h2>Build my roadmap</h2>

          <div className="form-group">
            <label>Career goal</label>
            <select value={careerGoal} onChange={(e) => setCareerGoal(e.target.value)}>
              {CAREER_GOALS.map(g => (
                <option key={g} value={g}>{g}</option>
              ))}
            </select>
          </div>

          {/* Skill tag input component */}
          <SkillInput skills={skills} setSkills={setSkills} />

          {error && <p className="error-msg">{error}</p>}

          <button
            className="generate-btn"
            onClick={handleGenerate}
            disabled={loading}
          >
            {loading ? 'Generating…' : '✨ Generate Roadmap'}
          </button>
        </div>

        {/* Right panel: roadmap results */}
        <div className="roadmap-panel">

          {/* Show newly generated roadmap first */}
          {newRoadmap && (
            <div>
              <h3 className="panel-heading">✅ Your new roadmap</h3>
              <RoadmapCard roadmap={newRoadmap} onMarkTopic={handleMarkTopic} />
            </div>
          )}

          {/* Show previously saved roadmaps */}
          {roadmaps.length > 0 && (
            <div>
              <h3 className="panel-heading">📂 Saved roadmaps</h3>
              {roadmaps.map(rm => (
                <RoadmapCard key={rm.id} roadmap={rm} onMarkTopic={handleMarkTopic} />
              ))}
            </div>
          )}

          {/* Empty state */}
          {roadmaps.length === 0 && !newRoadmap && (
            <div className="empty-state">
              <p>No roadmaps yet. Fill in the form and hit Generate! 👈</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

export default DashboardPage;
